import GoogleChrome from "./google-chrome"

export default function Page() {
  return (
    <div className="px-4 py-10 md:px-6 md:py-14">
      <GoogleChrome />
    </div>
  )
}

import type { CSSProperties, ReactNode } from "react"

import { cn } from "@/lib/utils"

export type BrowserViewportProps = {
  className?: string
  /** Minimum height when the viewport is empty (default `32rem`) */
  minHeight?: string | number
  /** e.g. `"16 / 9"` — keeps the content area proportional when set */
  aspectRatio?: string
  /** Image URL — scaled to cover the viewport */
  src?: string
  alt?: string
  /** Video URL — scaled to cover the viewport (muted, looped, inline for demos) */
  videoSrc?: string
  poster?: string
  /** Autoplay video when `videoSrc` is set (default `true`) */
  autoPlay?: boolean
  children?: ReactNode
}

export default function BrowserViewport({
  className,
  minHeight = "32rem",
  aspectRatio,
  src,
  alt = "",
  videoSrc,
  poster,
  autoPlay = true,
  children,
}: BrowserViewportProps) {
  const style = {
    ...(aspectRatio ? { aspectRatio } : {}),
    minHeight: typeof minHeight === "number" ? `${minHeight}px` : minHeight,
  } satisfies CSSProperties

  const mediaClass = "gc-viewport-media"

  return (
    <div className={cn("gc-viewport", className)} style={style}>
      {children ? (
        <div className="gc-viewport-slot">{children}</div>
      ) : videoSrc ? (
        <video
          className={mediaClass}
          src={videoSrc}
          poster={poster}
          muted
          loop
          playsInline
          autoPlay={autoPlay}
        />
      ) : src ? (
        // eslint-disable-next-line @next/next/no-img-element -- registry block; consumers may swap for next/image
        <img className={mediaClass} src={src} alt={alt} />
      ) : null}
    </div>
  )
}

import { chromeConfig } from "../lib/config"

export default function ProfileAvatar() {
  return (
    <span
      className="gc-profile"
      style={{ backgroundColor: chromeConfig.profileBg }}
      aria-hidden
    >
      <span className="gc-profile-letter">{chromeConfig.profileInitial}</span>
    </span>
  )
}

const SQUARES = [
  "#4285F4",
  "#EA4335",
  "#FBBC05",
  "#34A853",
  "#4285F4",
  "#EA4335",
  "#34A853",
  "#FBBC05",
  "#EA4335",
] as const

export default function AppsIcon() {
  return (
    <span className="gc-apps-icon" aria-hidden>
      {SQUARES.map((fill, i) => (
        <span key={i} className="gc-apps-square" style={{ backgroundColor: fill }} />
      ))}
    </span>
  )
}

import { cn } from "@/lib/utils"

type OmniboxTypingTextProps = {
  displayText: string
  showCursor: boolean
  caretSolid: boolean
  textClassName?: string
  caretClassName?: string
}

export default function OmniboxTypingText({
  displayText,
  showCursor,
  caretSolid,
  textClassName = "gc-omnibox-text",
  caretClassName = "gc-omnibox-caret",
}: OmniboxTypingTextProps) {
  return (
    <span className="gc-omnibox-typing" aria-hidden>
      <span className={cn(textClassName, !displayText && "gc-omnibox-text--measure")}>
        {displayText || "\u200b"}
      </span>
      {showCursor ? (
        <span
          className={cn(caretClassName, caretSolid && `${caretClassName}--solid`)}
          aria-hidden
        />
      ) : null}
    </span>
  )
}

import { useLayoutEffect, useReducer, useSyncExternalStore } from "react"

import {
  BETWEEN_MS,
  DELETE_CHAR_MS_FAST,
  DELETE_CHAR_MS_SLOW,
  HOLD_MS,
  START_DELAY_MS,
  TYPE_CHAR_MS_FAST,
  TYPE_CHAR_MS_SLOW,
} from "../lib/typing-animation"

export type OmniboxTypingOptions = {
  /** Phrases to cycle through in the omnibox */
  prompts: readonly string[]
  typeCharMsFast?: number
  typeCharMsSlow?: number
  deleteCharMsFast?: number
  deleteCharMsSlow?: number
  holdMs?: number
  betweenMs?: number
  startDelayMs?: number
}

type Phase = "idle" | "typingIn" | "hold" | "typingOut" | "between"

type State = {
  phase: Phase
  promptIdx: number
  charIdx: number
}

type Action =
  | { type: "ADVANCE_CHAR" }
  | { type: "SET_PHASE"; phase: Phase; charIdx?: number; promptIdx?: number }
  | { type: "REWIND_CHAR" }

function jitter(ms: number, spread = 0.1): number {
  const delta = ms * spread * (Math.random() * 2 - 1)
  return Math.max(10, Math.round(ms + delta))
}

function typeDelayMs(charIdx: number, len: number, fast: number, slow: number): number {
  if (len <= 0) return slow
  const t = charIdx / len
  const ease = Math.pow(1 - t, 0.32)
  return jitter(Math.round(fast + (slow - fast) * ease))
}

function deleteDelayMs(charIdx: number, len: number, fast: number, slow: number): number {
  if (len <= 0) return slow
  const t = charIdx / len
  const ease = Math.pow(t, 0.4)
  return jitter(Math.round(fast + (slow - fast) * ease))
}

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

export function useOmniboxTyping({
  prompts,
  typeCharMsFast = TYPE_CHAR_MS_FAST,
  typeCharMsSlow = TYPE_CHAR_MS_SLOW,
  deleteCharMsFast = DELETE_CHAR_MS_FAST,
  deleteCharMsSlow = DELETE_CHAR_MS_SLOW,
  holdMs = HOLD_MS,
  betweenMs = BETWEEN_MS,
  startDelayMs = START_DELAY_MS,
}: OmniboxTypingOptions) {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer,
  )

  const [state, dispatch] = useReducer(reducer, {
    phase: "idle",
    promptIdx: 0,
    charIdx: 0,
  })

  const { phase, promptIdx, charIdx } = state
  const text = prompts[promptIdx] ?? ""
  const len = text.length

  const displayText = reducedMotion ? (prompts[0] ?? "") : text.slice(0, charIdx)
  const showCursor = !reducedMotion
  const caretSolid = phase === "typingIn" || phase === "typingOut"
  const isActive =
    !reducedMotion &&
    (phase === "typingIn" || phase === "hold" || phase === "typingOut" || charIdx > 0)

  useLayoutEffect(() => {
    if (reducedMotion || prompts.length === 0) return

    let t: ReturnType<typeof setTimeout>

    switch (phase) {
      case "idle":
        t = setTimeout(() => dispatch({ type: "SET_PHASE", phase: "typingIn" }), startDelayMs)
        break

      case "typingIn":
        if (charIdx < len) {
          t = setTimeout(
            () => dispatch({ type: "ADVANCE_CHAR" }),
            typeDelayMs(charIdx, len, typeCharMsFast, typeCharMsSlow),
          )
        } else {
          dispatch({ type: "SET_PHASE", phase: "hold" })
        }
        break

      case "hold":
        t = setTimeout(() => dispatch({ type: "SET_PHASE", phase: "typingOut" }), holdMs)
        break

      case "typingOut":
        if (charIdx > 0) {
          t = setTimeout(
            () => dispatch({ type: "REWIND_CHAR" }),
            deleteDelayMs(charIdx, len, deleteCharMsFast, deleteCharMsSlow),
          )
        } else {
          dispatch({ type: "SET_PHASE", phase: "between", charIdx: 0 })
        }
        break

      case "between":
        t = setTimeout(() => {
          const next = (promptIdx + 1) % prompts.length
          dispatch({
            type: "SET_PHASE",
            phase: "typingIn",
            charIdx: 0,
            promptIdx: next,
          })
        }, betweenMs)
        break
    }

    return () => clearTimeout(t)
  }, [
    reducedMotion,
    phase,
    charIdx,
    len,
    promptIdx,
    prompts.length,
    typeCharMsFast,
    typeCharMsSlow,
    deleteCharMsFast,
    deleteCharMsSlow,
    holdMs,
    betweenMs,
    startDelayMs,
  ])

  return { displayText, showCursor, caretSolid, isActive }
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "ADVANCE_CHAR":
      return { ...state, charIdx: state.charIdx + 1 }
    case "REWIND_CHAR":
      return { ...state, charIdx: Math.max(0, state.charIdx - 1) }
    case "SET_PHASE":
      return {
        phase: action.phase,
        charIdx: action.charIdx ?? state.charIdx,
        promptIdx: action.promptIdx ?? state.promptIdx,
      }
    default:
      return state
  }
}

export const chromeConfig = {
  tabTitle: "New Tab",
  omniboxPlaceholder: "Search Google or type a URL",
  /** Default omnibox typewriter phrases — pass your own to `GoogleChrome` for SaaS demos */
  omniboxTypingPrompts: ["facebook.com"] as const,
  bookmarksAppsLabel: "Apps",
  profileInitial: "j",
  profileBg: "#14b8a6",
} as const

/** Eased type speed (ms per character) */
export const TYPE_CHAR_MS_SLOW = 72
export const TYPE_CHAR_MS_FAST = 28

/** Eased delete speed (ms per character) */
export const DELETE_CHAR_MS_SLOW = 42
export const DELETE_CHAR_MS_FAST = 14

/** Pause on full phrase before deleting */
export const HOLD_MS = 2200

/** Pause after clearing before typing again */
export const BETWEEN_MS = 420

/** Pause before the first keystroke (simulates focus / click) */
export const START_DELAY_MS = 680

/* google-chrome — scoped light/dark via .dark ancestor */

.gc-root {
  --gc-shell-bg: #dee1e6;
  --gc-border: rgb(0 0 0 / 0.12);
  --gc-ring: rgb(0 0 0 / 0.06);
  --gc-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.14);
  --gc-tabstrip-bg: #dee1e6;
  --gc-tab-bg: #ffffff;
  --gc-tab-fg: #3c4043;
  --gc-tab-close: #5f6368;
  --gc-toolbar-bg: #ffffff;
  --gc-toolbar-border: rgb(0 0 0 / 0.08);
  --gc-nav-fg: #5f6368;
  --gc-nav-disabled: rgb(95 99 104 / 0.38);
  --gc-omnibox-bg: #f1f3f4;
  --gc-omnibox-fg: #202124;
  --gc-omnibox-placeholder: #5f6368;
  --gc-omnibox-caret: #1a73e8;
  --gc-omnibox-focus-ring: rgb(26 115 232 / 0.18);
  --gc-menu-fg: #5f6368;
  --gc-bookmarks-bg: #ffffff;
  --gc-bookmarks-fg: #3c4043;
  --gc-viewport-bg: #ffffff;
  --gc-new-tab-btn: #5f6368;
  /* High-contrast initial on teal in site light mode */
  --gc-profile-letter-fg: oklch(0.995 0.01 195);
  --gc-profile-letter-shadow: oklch(0.25 0.06 195 / 0.22);
}

.dark .gc-root {
  --gc-shell-bg: #202124;
  --gc-border: rgb(255 255 255 / 0.1);
  --gc-ring: rgb(0 0 0 / 0.35);
  --gc-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.5);
  --gc-tabstrip-bg: #202124;
  --gc-tab-bg: #323639;
  --gc-tab-fg: #e8eaed;
  --gc-tab-close: #9aa0a6;
  --gc-toolbar-bg: #323639;
  --gc-toolbar-border: rgb(255 255 255 / 0.06);
  --gc-nav-fg: #9aa0a6;
  --gc-nav-disabled: rgb(154 160 166 / 0.35);
  --gc-omnibox-bg: #202124;
  --gc-omnibox-fg: #e8eaed;
  --gc-omnibox-placeholder: #9aa0a6;
  --gc-omnibox-caret: #8ab4f8;
  --gc-omnibox-focus-ring: rgb(138 180 248 / 0.22);
  --gc-menu-fg: #9aa0a6;
  --gc-bookmarks-bg: #323639;
  --gc-bookmarks-fg: #e8eaed;
  --gc-viewport-bg: #202124;
  --gc-new-tab-btn: #9aa0a6;
  /* Slightly softer glyph on teal when site is dark (less blow-out vs white) */
  --gc-profile-letter-fg: oklch(0.97 0.028 190);
  --gc-profile-letter-shadow: oklch(0.15 0.04 250 / 0.45);
}

.gc-shell {
  border: 1px solid var(--gc-border);
  background-color: var(--gc-shell-bg);
  box-shadow: var(--gc-shadow);
  outline: 1px solid var(--gc-ring);
  outline-offset: -1px;
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    sans-serif;
}

/* Tab strip */

.gc-tabstrip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: end;
  column-gap: 0.625rem;
  min-height: 2.75rem;
  padding: 0.375rem 0.5rem 0 0.875rem;
  background-color: var(--gc-tabstrip-bg);
}

.gc-traffic-lights {
  display: flex;
  align-self: center;
  align-items: center;
  gap: 0.5rem;
  padding-bottom: 0.15rem;
}

.gc-light {
  display: flex;
  width: 0.6875rem;
  height: 0.6875rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 9999px;
  padding: 0;
  box-shadow:
    inset 0 0 0 0.5px rgb(0 0 0 / 0.18),
    0 0.5px 0 rgb(255 255 255 / 0.35);
  cursor: default;
  transition: filter 0.12s ease;
}

.gc-traffic-lights:hover .gc-light {
  filter: brightness(0.92);
}

.gc-light-icon {
  flex-shrink: 0;
  opacity: 0;
  color: rgb(0 0 0 / 0.55);
  transition: opacity 0.12s ease;
}

.gc-traffic-lights:hover .gc-light-icon {
  opacity: 1;
}

.dark .gc-light {
  box-shadow:
    inset 0 0 0 0.5px rgb(0 0 0 / 0.45),
    0 0.5px 0 rgb(255 255 255 / 0.08);
}

.dark .gc-traffic-lights:hover .gc-light {
  filter: brightness(0.88);
}

.dark .gc-traffic-lights:hover .gc-light-icon {
  color: rgb(0 0 0 / 0.62);
}

.gc-light-close {
  background-color: #ff5f57;
}

.gc-light-minimize {
  background-color: #febc2e;
}

.gc-light-maximize {
  background-color: #28c840;
}

.gc-tabs {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: flex-end;
  gap: 0.125rem;
}

.gc-tab {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 0.375rem;
  width: clamp(9.5rem, 32vw, 11.75rem);
  min-width: 9.5rem;
  max-width: 11.75rem;
  flex-shrink: 0;
  border-radius: 0.5rem 0.5rem 0 0;
  padding: 0.5rem 0.375rem 0.5rem 0.75rem;
  font-size: 0.8125rem;
  line-height: 1.2;
  color: var(--gc-tab-fg);
}

.gc-tab-active {
  background-color: var(--gc-tab-bg);
}

.gc-tab-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gc-tab-close {
  display: flex;
  align-self: center;
  justify-self: end;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  margin-right: 0.0625rem;
  border: none;
  border-radius: 9999px;
  background: transparent;
  padding: 0;
  color: var(--gc-tab-close);
  opacity: 0.85;
}

.gc-tab-close:hover {
  opacity: 1;
}

.gc-new-tab {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  margin-bottom: 0.5rem;
  border: none;
  background: transparent;
  padding: 0;
  color: var(--gc-new-tab-btn);
}

/* Toolbar */

.gc-toolbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  box-sizing: border-box;
  min-height: 2.625rem;
  border-bottom: 1px solid var(--gc-toolbar-border);
  background-color: var(--gc-toolbar-bg);
  padding: 0.3125rem 0.875rem;
}

.gc-nav {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.0625rem;
}

.gc-nav-btn {
  display: flex;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 9999px;
  background: transparent;
  padding: 0;
  color: var(--gc-nav-fg);
}

.gc-nav-btn:disabled {
  color: var(--gc-nav-disabled);
  cursor: default;
}

.gc-omnibox {
  --gc-omnibox-track: calc(0.8125rem * 1.2);
  display: flex;
  box-sizing: border-box;
  min-width: 0;
  min-height: calc(var(--gc-omnibox-track) + 0.5rem);
  flex: 1;
  align-items: center;
  border: 1px solid transparent;
  border-radius: 9999px;
  background-color: var(--gc-omnibox-bg);
  padding: 0.25rem 1.125rem;
  transition:
    box-shadow 0.28s ease,
    border-color 0.2s ease;
}

.gc-omnibox--active {
  border-color: transparent;
  box-shadow: 0 0 0 1px var(--gc-omnibox-focus-ring);
}

.gc-omnibox-typing {
  display: inline-flex;
  min-width: 0;
  min-height: var(--gc-omnibox-track);
  flex: 1;
  align-items: center;
  overflow: hidden;
  font-size: 0.8125rem;
  line-height: 1.2;
}

.gc-omnibox-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: inherit;
  line-height: inherit;
  color: var(--gc-omnibox-fg);
  user-select: none;
}

.gc-omnibox-text--measure {
  opacity: 0;
}

.gc-omnibox-caret {
  display: inline-block;
  flex-shrink: 0;
  width: 1px;
  height: var(--gc-omnibox-track);
  margin-left: 1px;
  background-color: var(--gc-omnibox-caret);
  animation: gc-omnibox-caret-blink 1s step-end infinite;
}

.gc-omnibox-caret--solid {
  animation: none;
  opacity: 1;
}

@keyframes gc-omnibox-caret-blink {
  0%, 45% { opacity: 1; }
  55%, 100% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .gc-omnibox {
    transition: none;
  }

  .gc-omnibox-caret {
    animation: none;
    opacity: 0;
  }
}

.gc-toolbar-actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.375rem;
}

.gc-profile {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  border-radius: 9999px;
}

.gc-profile-letter {
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0;
  text-transform: lowercase;
  color: var(--gc-profile-letter-fg);
  text-shadow: 0 0.5px 0 var(--gc-profile-letter-shadow);
  /* Optically center lowercase glyphs (e.g. j) that have descenders */
  transform: translateY(-0.08em);
}

.gc-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  padding: 0.25rem;
  color: var(--gc-menu-fg);
}

/* Bookmarks */

.gc-bookmarks {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border-bottom: 1px solid var(--gc-toolbar-border);
  background-color: var(--gc-bookmarks-bg);
  padding: 0.375rem 0.875rem;
  font-size: 0.8125rem;
  color: var(--gc-bookmarks-fg);
}

.gc-apps-icon {
  display: grid;
  grid-template-columns: repeat(3, 4px);
  gap: 1px;
  flex-shrink: 0;
}

.gc-apps-square {
  width: 4px;
  height: 4px;
  border-radius: 0.5px;
}

.gc-bookmarks-label {
  font-weight: 400;
}

/* Viewport */

.gc-viewport {
  position: relative;
  width: 100%;
  overflow: hidden;
  background-color: var(--gc-viewport-bg);
}

.gc-viewport-media {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  border: none;
  object-fit: cover;
  object-position: center;
}

.gc-viewport-slot {
  position: absolute;
  inset: 0;
  display: flex;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.gc-viewport-slot > img,
.gc-viewport-slot > video,
.gc-viewport-slot > picture,
.gc-viewport-slot > iframe,
.gc-viewport-slot :is(img, video, iframe) {
  display: block;
  width: 100%;
  height: 100%;
  border: none;
  object-fit: cover;
  object-position: center;
}

.gc-viewport-slot > * {
  flex: 1;
  min-width: 0;
  min-height: 0;
}
